861	
862	static bool ui_switch_to_watch_match(const char* asr_text)
863	{
864	    char norm[512];
865	    size_t w = 0;
866	    const unsigned char* r = (const unsigned char*)asr_text;
867	
868	    while (*r && w < sizeof(norm) - 1) {
869	        if (*r < 0x80) {
870	            if (isalnum(*r)) norm[w++] = (char)tolower(*r);
871	            r++;
872	            continue;
873	        }
874	        /* Skip CJK/full-width punctuation (same as wake_word_match) */
875	        if ((r[0] == 0xE3 || r[0] == 0xEF
876	             || (r[0] == 0xE2 && r[1] == 0x80))
877	            && r[1] != '\0' && r[2] != '\0') {
878	            r += 3; continue;
879	        }
880	        norm[w++] = (char)*r++;
881	    }
882	    norm[w] = '\0';
883	
884	    for (size_t i = 0;
885	         i < sizeof(SWITCH_TO_WATCH_KEYWORDS) / sizeof(SWITCH_TO_WATCH_KEYWORDS[0]);
886	         i++) {
887	        if (strstr(norm, SWITCH_TO_WATCH_KEYWORDS[i]) != NULL) {
888	            syslog(LOG_INFO, "[%s] UI switch keyword: \"%s\" (norm=\"%s\")\n",
889	                TAG, SWITCH_TO_WATCH_KEYWORDS[i], norm);
890	            return true;
891	        }
892	    }
893	    return false;
894	}
