122	 *
123	 * FLAT build 下 watch 与 ai_agent 同镜像，直接链接 ai_agent_main。
124	 * task_create 非阻塞，不影响 LVGL 主线程。
125	 */
126	static void agent_autostart(void)
127	{
128	  extern int ai_agent_main(int argc, char *argv[]);
129	
130	  if (g_agent_started)
131	    {
