154	/**
155	 * @brief 延迟唤醒启动定时器：等 WiFi + ai_agent 都就绪后再启动唤醒监听
156	 */
157	static void deferred_wake_start_timer_cb(lv_timer_t *timer)
158	{
159	    extern bool voice_channel_is_ready(void);
160	    extern int voice_channel_start_wake(void);
161	
162	    bool wifi_ok = settings_wifi_is_connected();
163	    bool voice_ok = voice_channel_is_ready();
164	
165	    WATCH_DBG_LOG("[LAUNCHER] wake start check #%d: wifi=%d voice=%d",
166	                  ++s_wake_attempts, wifi_ok, voice_ok);
167	
168	    if (wifi_ok && voice_ok) {
169	        WATCH_DBG_LOG("[LAUNCHER] both ready, starting wake-word listening");
170	        voice_channel_start_wake();
171	        if (timer == s_wake_timer) {
172	            s_wake_timer = NULL;
173	        }
174	        lv_timer_del(timer);  /* stop this timer */
175	        return;
176	    }
177	
178	    /* After 10s without WiFi (10 attempts × 1s), play no-network alert once */
179	    if (s_wake_attempts == 10) {
180	        tool_system_alert_play(16, 0);
181	    }
182	
183	    /* Safety: give up after 180 attempts (180 seconds) */
184	    if (s_wake_attempts >= 180) {
185	        WATCH_DBG_LOG("[LAUNCHER] wake start timeout, giving up (wifi=%d voice=%d)",
186	                      wifi_ok, voice_ok);
187	        if (timer == s_wake_timer) {
188	            s_wake_timer = NULL;
189	        }
190	        lv_timer_del(timer);
191	    }
192	}
