218	void launcher_stop_voice_for_watch(void)
219	{
220	  extern int voice_channel_stop(void);
221	  extern void volc_e2e_stop(void);
222	  extern void agent_request_shutdown(void);
223	  extern bool agent_is_running(void);
224	
225	  WATCH_DBG_LOG("[LAUNCHER] stop voice+agent for watch (runtime switch)");
226	
227	  /* 取消延迟唤醒定时器，避免 agent 停止后又被它拉起唤醒监听 */
228	  if (s_wake_timer != NULL)
229	    {
230	      lv_timer_del(s_wake_timer);
231	      s_wake_timer = NULL;
232	    }
233	
234	  /* 停语音会话线程：voice_channel_stop 内部 capture_close 解除
235	   * read 阻塞并 join 会话线程；未运行时返回错误，忽略 */
236	  voice_channel_stop();
237	
238	  /* 断开 E2E 语音链路（内部有锁，未建立时安全返回） */
239	  volc_e2e_stop();

239	  volc_e2e_stop();
240	
241	  /* 请求 ai_agent 退出并同步等待 teardown（主循环 1s 轮询粒度，
242	   *  teardown 含 500ms 的线程退出等待） */
243	  agent_request_shutdown();
244	  int wait_ms = 0;
245	  while (agent_is_running() && wait_ms < 5000)
246	    {
247	      usleep(100 * 1000);
248	      wait_ms += 100;
249	    }
250	  if (agent_is_running())
251	    {
252	      WATCH_DBG_LOG("[LAUNCHER] WARN: ai_agent teardown timeout");
253	    }
254	
255	  /* 允许切回表情模式时重新拉起 */
256	  g_agent_started = false;
257	}
