97	/* Square-law mapping from percent to hardware value.
98	 * Spreads the quiet range and compresses the loud end to match
99	 * human loudness perception.
100	 *
101	 *   hw = 1000 * (pct / 100)^2     (0% → 0, 100% → 1000)
102	 *
103	 *   pct   0%   10%   20%   30%   50%   70%   100%
104	 *   hw     0    10    40    90   250   490   1000
105	 *   DAC    0    85   136   166   204   229    255
106	 */
107	static int percent_to_hw(int percent)
108	{
109	  if (percent <= 0)
110	    {
111	      return 0;
112	    }
113	  if (percent >= WATCH_VOLUME_PERCENT_MAX)
114	    {
115	      return WATCH_VOLUME_HW_MAX;
116	    }
117	  /* k = 2.0: hw ∝ percent^2 */
118	  return (int)((int64_t)WATCH_VOLUME_HW_MAX * percent * percent /
119	               (100 * 100));
120	}
121	
122	/* Inverse: sqrt of hardware proportion */
123	static int hw_to_percent(int value)
124	{
125	  if (value <= 0)
126	    {
127	      return 0;
128	    }
129	  if (value >= WATCH_VOLUME_HW_MAX)
130	    {
131	      return WATCH_VOLUME_PERCENT_MAX;
132	    }
133	  return (int)(100.0f * sqrtf((float)value / WATCH_VOLUME_HW_MAX));
134	}
