40	int esp32s3_watch_audio_setvolume(uint16_t volume)
41	{
42	  struct audio_caps_desc_s cap_desc;
43	  int fd;
44	  int ret = OK;
45	
46	  if (volume > 1000)
47	    {
48	      volume = 1000;
49	    }
50	
51	  pthread_mutex_lock(&g_audio_mutex);
52	
53	  g_watch_volume = volume;
54	
55	  /* Open the device briefly to set volume, then close immediately.
56	   * Keeping a persistent fd would reserve an audio session and
57	   * block nxplayer (TTS) from creating its own session. */
58	
59	  fd = open(AUDIO_DEVICE_PATH, O_RDWR);
60	  if (fd >= 0)
61	    {
62	      cap_desc.caps.ac_len       = sizeof(struct audio_caps_s);
63	      cap_desc.caps.ac_type      = AUDIO_TYPE_FEATURE;
64	      cap_desc.caps.ac_format.hw = AUDIO_FU_VOLUME;
65	      cap_desc.caps.ac_controls.hw[0] = volume;
66	
67	      ret = ioctl(fd, AUDIOIOC_CONFIGURE, (unsigned long)&cap_desc);
68	      close(fd);
69	    }
70	  else
71	    {
72	      ret = -errno;
73	    }
74	
75	  pthread_mutex_unlock(&g_audio_mutex);
76	
77	  return (ret < 0) ? -errno : OK;
78	}
