81	{
82	  if (volume == NULL)
83	    {
84	      return -EINVAL;
85	    }
86	
87	  pthread_mutex_lock(&g_audio_mutex);
88	  *volume = g_watch_volume;
89	  pthread_mutex_unlock(&g_audio_mutex);
90	
91	  return OK;
92	}
