3045	       * Channel mask = (1 << total_slot) - 1
3046	       */
3047	
3048	      modifyreg32(I2S_TX_TDM_CTRL_REG(priv->config->port),
3049	                  I2S_TX_TDM_TOT_CHAN_NUM_M,
3050	                  FIELD_TO_VALUE(I2S_TX_TDM_TOT_CHAN_NUM,
3051	                                 priv->config->total_slot - 1));
