112	/* Batch recognition: run the streaming path once so callers that only
113	 * use voice_asr_recognize() (tools, tests) still work. */
114	static int e2e_recognize(const unsigned char* pcm_data, size_t pcm_len,
115	    char* text_out, size_t text_cap)
116	{
117	    if (!pcm_data || pcm_len == 0 || !text_out || text_cap == 0) {
118	        return -EINVAL;
119	    }
120	    text_out[0] = '\0';
121	
122	    void* h = NULL;
123	    int ret = e2e_stream_open(&h);
124	    if (ret != 0) return ret;
125	
126	    const size_t chunk = 640; /* 20ms @16k mono 16bit */
127	    for (size_t off = 0; off < pcm_len; off += chunk) {
128	        size_t n = pcm_len - off;
129	        if (n > chunk) n = chunk;
130	        ret = e2e_stream_send(h, pcm_data + off, n);
131	        if (ret != 0) {
132	            e2e_stream_abort(h);
133	            return ret;
134	        }
135	        usleep(20000); /* pace the uplink like a live capture would */
136	    }
137	
138	    /* Wait for the server to declare the utterance finished. */
139	    for (int i = 0; i < 100; i++) {
140	        ret = e2e_stream_try_recv(h, text_out, text_cap);
141	        if (ret > 0) {
142	            /* Batch callers do not speak through this session, so drop
143	             * the TTS channel the ASREnded handler just claimed. */
144	            volc_e2e_tts_abort();
145	            e2e_stream_abort(h);
146	            return 0;
147	        }
148	        if (ret < 0) {
149	            e2e_stream_abort(h);
150	            return ret;
151	        }
152	        usleep(100000);
153	    }
154	
155	    e2e_stream_abort(h);
156	    return -ETIMEDOUT;
157	}
