673	static void write_be32(unsigned char *buf, size_t off, uint32_t val)
674	{
675	    buf[off] = (unsigned char)((val >> 24) & 0xFF);
676	    buf[off + 1] = (unsigned char)((val >> 16) & 0xFF);
677	    buf[off + 2] = (unsigned char)((val >> 8) & 0xFF);
678	    buf[off + 3] = (unsigned char)(val & 0xFF);
679	}
