681	static int send_client_frame(tls_ctx_t *ctx, uint32_t event_id,
682	    const char *session_id, const unsigned char *payload, size_t plen)
683	{
684	    if (ctx == NULL || ctx->net.fd < 0) return -EINVAL;
685	
686	    size_t sid_len = session_id ? strlen(session_id) : 0;
687	    bool is_connect_event = (event_id == EVENT_START_CONNECTION
688	                             || event_id == EVENT_FINISH_CONNECTION);
689	
690	    size_t frame_len;
691	    if (is_connect_event)
692	        frame_len = VOLC_HDR_SIZE + 4 + 4 + plen;
693	    else
694	        frame_len = VOLC_HDR_SIZE + 4 + 4 + sid_len + 4 + plen;
695	
696	    unsigned char *frame = malloc(frame_len);
697	    if (!frame) return -ENOMEM;
698	
699	    size_t off = 0;
700	    frame[off++] = VOLC_PROTO_VER;
701	    frame[off++] = VOLC_MSG_FULL_REQ | VOLC_FLAG_EVENT;
702	    frame[off++] = VOLC_SER_JSON;
703	    frame[off++] = 0x00;
704	
705	    write_be32(frame, off, event_id);
706	    off += 4;
707	
708	    if (!is_connect_event) {
709	        write_be32(frame, off, (uint32_t)sid_len);
710	        off += 4;
711	        if (sid_len > 0) {
712	            memcpy(frame + off, session_id, sid_len);
713	            off += sid_len;
714	        }
715	    }
716	
717	    write_be32(frame, off, (uint32_t)plen);
718	    off += 4;
719	    if (plen > 0) memcpy(frame + off, payload, plen);
720	
721	    int ret = ws_send_binary(ctx, frame, frame_len);
722	    free(frame);
723	    return ret;
724	}
