726	static int send_audio_frame(tls_ctx_t *ctx, const char *session_id,
727	    const unsigned char *audio, size_t alen)
728	{
729	    if (ctx == NULL || ctx->net.fd < 0 || session_id == NULL) return -EINVAL;
730	
731	    size_t sid_len = strlen(session_id);
732	    if (sid_len == 0) return -EINVAL;
733	
734	    size_t frame_len = VOLC_HDR_SIZE + 4 + 4 + sid_len + 4 + alen;
735	    unsigned char *frame = malloc(frame_len);
736	    if (!frame) return -ENOMEM;
737	
738	    size_t off = 0;
739	    frame[off++] = VOLC_PROTO_VER;
740	    frame[off++] = VOLC_MSG_AUDIO_REQ | VOLC_FLAG_EVENT;
741	    frame[off++] = VOLC_SER_RAW;
742	    frame[off++] = 0x00;
743	
744	    write_be32(frame, off, EVENT_TASK_REQUEST);
745	    off += 4;
746	
747	    write_be32(frame, off, (uint32_t)sid_len);
748	    off += 4;
749	    memcpy(frame + off, session_id, sid_len);
750	    off += sid_len;
751	
752	    write_be32(frame, off, (uint32_t)alen);
753	    off += 4;
