480	{
481	    unsigned char key_raw[16];
482	    unsigned char key_b64[32];
483	    size_t key_b64_len;
484	    entropy_func(NULL, key_raw, sizeof(key_raw));
485	    mbedtls_base64_encode(key_b64, sizeof(key_b64), &key_b64_len,
486	        key_raw, sizeof(key_raw));
487	
488	    char req[1024];
489	    int n = snprintf(req, sizeof(req),
490	        "GET %s HTTP/1.1\r\n"
491	        "Host: %s\r\n"
492	        "Upgrade: websocket\r\n"
493	        "Connection: Upgrade\r\n"
494	        "Sec-WebSocket-Key: %.*s\r\n"
495	        "Sec-WebSocket-Version: 13\r\n"
496	        "X-Api-App-ID: %s\r\n"
497	        "X-Api-Access-Key: %s\r\n"
498	        "X-Api-Resource-Id: %s\r\n"
499	        "X-Api-App-Key: %s\r\n"
500	        "\r\n",
501	        path, host, (int)key_b64_len, key_b64,
502	        s_app_id, s_token, VOLC_RESOURCE, VOLC_APP_KEY);
503	
504	    if (n <= 0 || n >= (int)sizeof(req)) return -EOVERFLOW;
505	
506	    syslog(LOG_INFO, "[%s] WS handshake: %s (app_id=%.6s...)\n", TAG, path, s_app_id);
507	
508	    int ret = tls_write_all(ctx, (const unsigned char *)req, (size_t)n);
509	    if (ret != 0) return ret;
510	
511	    char resp[2048];
512	    size_t rlen = 0;
513	    while (rlen < sizeof(resp) - 1) {
514	        int r = mbedtls_ssl_read(&ctx->ssl,
515	            (unsigned char *)resp + rlen, sizeof(resp) - 1 - rlen);
516	        if (r > 0) {
517	            rlen += (size_t)r;
518	            resp[rlen] = '\0';
519	            if (strstr(resp, "\r\n\r\n")) break;
520	        } else if (r == 0 || r == MBEDTLS_ERR_SSL_PEER_CLOSE_NOTIFY) {
521	            return -ECONNRESET;
522	        } else if (r != MBEDTLS_ERR_SSL_WANT_READ) {
523	            return -EIO;
524	        }
525	    }
526	
527	    int status = 0;
528	    if (sscanf(resp, "HTTP/1.1 %d", &status) != 1 || status != 101) {
529	        syslog(LOG_ERR, "[%s] WS upgrade failed: HTTP %d\n", TAG, status);
530	        return -EPROTO;
531	    }
532	
533	    syslog(LOG_INFO, "[%s] WS upgrade OK\n", TAG);
534	    return 0;
535	}

