896	static int parse_server_frame(const unsigned char *frame, size_t frame_len,
897	    uint32_t *out_event, char *session_id, size_t sid_cap,
898	    unsigned char **out_payload, size_t *out_plen)
899	{
900	    if (frame_len < VOLC_HDR_SIZE) return -EINVAL;
901	
902	    uint8_t msg_type = frame[1] & 0xF0;
903	
904	    if (msg_type == VOLC_MSG_ERROR) {
905	        if (frame_len >= VOLC_HDR_SIZE + 8) {
906	            *out_event = EVENT_DIALOG_ERROR;
907	            uint32_t err_code = read_be32(frame, 4);
908	            uint32_t err_len = read_be32(frame, 8);
909	            syslog(LOG_ERR, "[%s] server error: code=%u\n", TAG, err_code);
910	            if (err_len > 0 && VOLC_HDR_SIZE + 8 + err_len <= frame_len) {
911	                *out_payload = (unsigned char *)(frame + VOLC_HDR_SIZE + 8);
912	                *out_plen = err_len;
913	            }
914	            session_id[0] = '\0';
915	            return 0;
916	        }
917	        return -EINVAL;
918	    }
919	
920	    if (msg_type != VOLC_MSG_FULL_RESP && msg_type != VOLC_MSG_AUDIO_RESP)
921	        return -EINVAL;
922	
923	    *out_event = read_be32(frame, 4);
924	
925	    if (msg_type == VOLC_MSG_AUDIO_RESP)
926	        *out_event = EVENT_TTS_RESPONSE;
927	
928	    size_t off = 8;
929	    if (off + 4 > frame_len) return -EINVAL;
930	    uint32_t sid_len = read_be32(frame, off);
931	    off += 4;
932	
933	    if (sid_len > 0) {
934	        if (off + sid_len > frame_len) return -EINVAL;
935	        if (sid_len >= sid_cap) sid_len = sid_cap - 1;
936	        memcpy(session_id, frame + off, sid_len);
937	        session_id[sid_len] = '\0';
938	        off += sid_len;
939	    } else {
940	        session_id[0] = '\0';
941	    }
942	
943	    if (off + 4 > frame_len) {
944	        *out_payload = NULL;
945	        *out_plen = 0;
946	        return 0;
947	    }
948	    uint32_t plen = read_be32(frame, off);
949	    off += 4;
950	
951	    if (off + plen > frame_len) return -EINVAL;
952	    *out_payload = (unsigned char *)(frame + off);
953	    *out_plen = plen;
954	    return 0;
955	}
