415	/* ========== TLS I/O (互斥锁保护) ========== */
416	
417	static int tls_write_all(tls_ctx_t *ctx, const unsigned char *buf, size_t len)
418	{
419	    if (ctx == NULL || ctx->net.fd < 0) return -EINVAL;
420	
421	    pthread_mutex_lock(&s_tls_mutex);
422	    size_t written = 0;
423	    while (written < len) {
424	        int ret = mbedtls_ssl_write(&ctx->ssl, buf + written, len - written);
425	        if (ret > 0) {
426	            written += (size_t)ret;
