445	static int tls_read_all(tls_ctx_t *ctx, unsigned char *buf, size_t len)
446	{
447	    if (ctx == NULL || ctx->net.fd < 0) return -EINVAL;
448	
449	    pthread_mutex_lock(&s_tls_mutex);
450	    size_t got = 0;
451	    while (got < len) {
452	        int ret = mbedtls_ssl_read(&ctx->ssl, buf + got, len - got);
453	        if (ret > 0) {
454	            got += (size_t)ret;
455	        } else if (ret == 0 || ret == MBEDTLS_ERR_SSL_PEER_CLOSE_NOTIFY) {
456	            syslog(LOG_INFO, "[%s] connection closed by peer\n", TAG);
457	            pthread_mutex_unlock(&s_tls_mutex);
