459	        } else if (ret == MBEDTLS_ERR_SSL_WANT_READ || ret == MBEDTLS_ERR_SSL_WANT_WRITE) {
460	            pthread_mutex_unlock(&s_tls_mutex);
461	            usleep(10000);
462	            pthread_mutex_lock(&s_tls_mutex);
