464	            syslog(LOG_ERR, "[%s] connection reset\n", TAG);
465	            pthread_mutex_unlock(&s_tls_mutex);
466	            return -ECONNRESET;
467	        } else {
468	            syslog(LOG_ERR, "[%s] ssl_read: -0x%04x\n", TAG, -ret);
469	            pthread_mutex_unlock(&s_tls_mutex);
470	            return -EIO;
